const dinosaurs = [
  {name:'Herrerasaurus',period:'TRIÁSICO TARDÍO · 231 MA',formation:'FORMACIÓN ISCHIGUALASTO',location:'SAN JUAN · ARGENTINA',etymology:'“Lagarto de Herrera”',length:'≈ 6 m',scale:'6 M',diet:'Carnívora',clade:'Saurischia',kind:'runner',palette:['#d6b56c','#9e663f','#673c2c','#f0d893'],description:'Uno de los dinosaurios más antiguos conocidos: ligero, bípedo y construido para moverse con rapidez.',note:'Su anatomía combina rasgos primitivos y especializados. Es una pieza clave para estudiar el origen de los dinosaurios.'},
  {name:'Stegosaurus',period:'JURÁSICO TARDÍO · 155—150 MA',formation:'FORMACIÓN MORRISON',location:'OESTE DE NORTEAMÉRICA',etymology:'“Lagarto con techo”',length:'≈ 7 m',scale:'7 M',diet:'Herbívora',clade:'Stegosauria',kind:'stego',palette:['#b9b66b','#687b52','#3e4935','#e7cf78'],description:'Un herbívoro de cabeza pequeña, grandes placas dorsales y una cola armada con cuatro largas púas.',note:'Las placas tenían vasos sanguíneos. Probablemente servían para exhibición y reconocimiento, aunque su función exacta sigue en discusión.'},
  {name:'Archaeopteryx',period:'JURÁSICO TARDÍO · 150 MA',formation:'CALIZAS DE SOLNHOFEN',location:'BAVIERA · ALEMANIA',etymology:'“Pluma antigua”',length:'≈ 50 cm',scale:'0.5 M',diet:'Carnívora',clade:'Avialae',kind:'archaeopteryx',palette:['#d3a66a','#8b5540','#473431','#eed8a0'],description:'Un pequeño dinosaurio emplumado con alas, dientes, garras en las manos y una larga cola ósea.',note:'Combina características de dinosaurios no avianos y aves. Sus fósiles ayudaron a revelar que las aves son dinosaurios vivos.'},
  {name:'Spinosaurus',period:'CRETÁCICO TARDÍO · 99—94 MA',formation:'GRUPO KEM KEM',location:'MARRUECOS · NORTE DE ÁFRICA',etymology:'“Lagarto de espinas”',length:'≈ 14 m*',scale:'14 M',diet:'Piscívora / carnívora',clade:'Spinosauridae',kind:'spino',palette:['#75a18b','#386b66','#23464a','#d6c176'],description:'Un terópodo alargado con hocico semejante al de un cocodrilo y una enorme vela sostenida por espinas vertebrales.',note:'Su modo de nadar y su postura siguen siendo debatidos. Cada nuevo fósil ha cambiado profundamente su reconstrucción. *Longitud estimada.'},
  {name:'Carnotaurus',period:'CRETÁCICO TARDÍO · 72—69 MA',formation:'FORMACIÓN LA COLONIA',location:'PATAGONIA · ARGENTINA',etymology:'“Toro carnívoro”',length:'≈ 7.5 m',scale:'7.5 M',diet:'Carnívora',clade:'Abelisauridae',kind:'carno',palette:['#c6754f','#793c38','#4a2830','#e7b56f'],description:'Terópodo de hocico corto, dos cuernos sobre los ojos, patas largas y brazos extraordinariamente reducidos.',note:'Impresiones de piel muestran un mosaico de escamas y protuberancias. Es uno de los terópodos con mejor evidencia de su superficie corporal.'},
  {name:'Triceratops',period:'CRETÁCICO TARDÍO · 68—66 MA',formation:'HELL CREEK / LANCE',location:'OESTE DE NORTEAMÉRICA',etymology:'“Rostro de tres cuernos”',length:'≈ 8—9 m',scale:'9 M',diet:'Herbívora',clade:'Ceratopsidae',kind:'trike',palette:['#b59e69','#6f654c','#413e33','#dfc585'],description:'Un herbívoro robusto con gola ósea, pico curvo y tres cuernos capaces de cambiar durante su crecimiento.',note:'Las heridas cicatrizadas sugieren que los cuernos participaron en combates. La gola también pudo funcionar como señal visual.'},
  {name:'Tyrannosaurus rex',period:'CRETÁCICO TARDÍO · 68—66 MA',formation:'HELL CREEK / LANCE',location:'OESTE DE NORTEAMÉRICA',etymology:'“Rey de los lagartos tiranos”',length:'≈ 12—13 m',scale:'13 M',diet:'Carnívora',clade:'Tyrannosauridae',kind:'rex',palette:['#a8a560','#5c6845','#354132','#d7bd70'],description:'Un depredador de cráneo enorme, sentidos desarrollados y una de las mordidas más poderosas entre los animales terrestres.',note:'No era solo carroñero: marcas de mordida cicatrizadas demuestran ataques a animales vivos. También aprovechaba cadáveres cuando podía.'}
];

